script:
(function () {
  'use strict';
  // Federal estate tax estimate for a death in 2026, following the Form 706 tax computation:
  //   gross estate - debts - funeral/settlement costs - state death tax - charity - marital
  //     = taxable estate
  //   tentative tax = unified rate schedule on (taxable estate + adjusted taxable gifts)
  //   applicable credit = rate schedule on (basic exclusion amount + DSUE)
  //   estate tax = tentative tax - applicable credit (not below zero)
  //   Assumes no gift tax was actually paid on lifetime gifts (they used the exclusion).
  //   Portable unused exclusion (DSUE) = lesser of the basic exclusion amount and
  //     (applicable exclusion - taxable estate - adjusted taxable gifts).
  // Verified (Node, scratch tests): rate schedule gives $345,800 on $1,000,000,
  //   $5,541,800 on $13,990,000 and $5,945,800 on $15,000,000 (Form 706 instructions, Table of
  //   Basic Exclusion Amounts). Default estate: $19.5M gross, $0.75M debts and costs ->
  //   taxable $18.75M, tentative $7,445,800, credit $5,945,800, tax $1,500,000 (= 40% x $3.75M).
  //   With $15M DSUE the same estate owes $0 and leaves $11.25M of exclusion unused.
  //
  // ---- 2026 FEDERAL ESTATE TAX CONSTANTS (deaths in calendar year 2026) ---------------
  // Basic exclusion amount: IRC 2010(c)(3) as amended by P.L. 119-21 section 70106;
  //   $15,000,000 for 2026 per Rev. Proc. 2025-32 section 3.14 and the Form 706
  //   instructions (Rev. July 2026). Indexed for inflation from 2027.
  // Rate schedule: IRC 2001(c); Form 706 instructions, Table A - Unified Rate Schedule.
  // Annual gift exclusion (hint text only): $19,000, Rev. Proc. 2025-32 section 4.42.
  var TAX_YEAR = 2026;
  var BASIC_EXCLUSION = 15000000;
  var RATE_TABLE = [ // [taxable amount over, tax on that amount, rate on the excess]
    [0, 0, 0.18], [10000, 1800, 0.20], [20000, 3800, 0.22], [40000, 8200, 0.24],
    [60000, 13000, 0.26], [80000, 18200, 0.28], [100000, 23800, 0.30], [150000, 38800, 0.32],
    [250000, 70800, 0.34], [500000, 155800, 0.37], [750000, 248300, 0.39], [1000000, 345800, 0.40]
  ];
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el || el.value === '') return 0;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function rateTax(amount) {
    if (!(amount > 0)) return 0;
    var row = RATE_TABLE[0];
    for (var i = 0; i < RATE_TABLE.length; i++) if (amount > RATE_TABLE[i][0]) row = RATE_TABLE[i];
    return row[1] + (amount - row[0]) * row[2];
  }

  function estate(p) {
    var gross = p.realEstate + p.invest + p.cash + p.retire + p.life + p.business + p.other;
    var deductions = p.debts + p.expenses + p.stateTax + p.charity + p.spouse;
    var taxable = Math.max(0, gross - deductions);
    var base = taxable + p.gifts;
    var exclusion = BASIC_EXCLUSION + Math.min(p.dsue, BASIC_EXCLUSION);
    var tentative = rateTax(base);
    var credit = rateTax(exclusion);
    var tax = Math.max(0, tentative - credit);
    var portable = Math.min(BASIC_EXCLUSION, Math.max(0, exclusion - base));
    return {
      gross: gross, taxable: taxable, base: base, exclusion: exclusion, tentative: tentative,
      credit: credit, tax: tax, above: Math.max(0, base - exclusion), portable: portable,
      net: gross - p.debts - p.expenses - p.stateTax - tax
    };
  }

  function fill(rows) {
    var body = document.getElementById('etBreakdown');
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      var th = document.createElement('th');
      th.setAttribute('scope', 'row');
      th.textContent = cells[0];
      var td = document.createElement('td');
      td.textContent = cells[1];
      tr.appendChild(th);
      tr.appendChild(td);
      body.appendChild(tr);
    });
  }
  function minus(v) { return v > 0 ? '−' + money.format(v) : money.format(0); }

  function clear() {
    ['etTax', 'etTaxable', 'etExclusion', 'etGross', 'etAbove', 'etEffective', 'etNet', 'etPortable'].forEach(function (id) { set(id, '–'); });
    fill([]);
    var note = document.getElementById('etNote');
    if (note) note.hidden = true;
  }

  function update() {
    var ids = { realEstate: 'etRealEstate', invest: 'etInvest', cash: 'etCash', retire: 'etRetire', life: 'etLife',
                business: 'etBusiness', other: 'etOther', debts: 'etDebts', expenses: 'etExpenses', spouse: 'etSpouse',
                charity: 'etCharity', gifts: 'etGifts', dsue: 'etDsue', stateTax: 'etStateTax' };
    var p = {}, bad = false;
    Object.keys(ids).forEach(function (k) {
      p[k] = num(ids[k]);
      if (!isFinite(p[k]) || p[k] < 0 || p[k] > 1e12) bad = true;
    });
    var msg = '';
    if (bad) msg = 'Enter each amount as a number of zero or more (leave unused fields at 0).';
    else {
      var gross = p.realEstate + p.invest + p.cash + p.retire + p.life + p.business + p.other;
      var left = gross - p.debts - p.expenses - p.stateTax;
      if (p.spouse + p.charity > Math.max(0, left) + 0.5 && p.spouse + p.charity > 0) {
        msg = 'The amounts left to a spouse and to charity are more than the estate has left after debts, costs and state tax (' + money.format(Math.max(0, left)) + ').';
      }
    }
    var error = document.getElementById('etError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }

    var r = estate(p);
    set('etTax', money.format(r.tax));
    set('etTaxable', money.format(r.taxable));
    set('etExclusion', money.format(r.exclusion));
    set('etGross', money.format(r.gross));
    set('etAbove', money.format(r.above));
    set('etEffective', r.gross > 0 ? (r.tax / r.gross * 100).toFixed(1) + '%' : '0.0%');
    set('etNet', money.format(r.net));
    set('etPortable', money.format(r.portable));

    fill([
      ['Gross estate', money.format(r.gross)],
      ['Debts and mortgages', minus(p.debts)],
      ['Funeral and settlement costs', minus(p.expenses)],
      ['State estate or inheritance tax', minus(p.stateTax)],
      ['Charitable deduction', minus(p.charity)],
      ['Marital deduction (left to a spouse)', minus(p.spouse)],
      ['Taxable estate', money.format(r.taxable)],
      ['Plus lifetime taxable gifts', money.format(p.gifts)],
      ['Amount the tax is figured on', money.format(r.base)],
      ['Tentative tax (rate schedule)', money.format(r.tentative)],
      ['Applicable credit on ' + money.format(r.exclusion) + ' of exclusion', minus(Math.min(r.credit, r.tentative))],
      ['Federal estate tax', money.format(r.tax)]
    ]);

    var notes = [];
    if (p.dsue > BASIC_EXCLUSION) notes.push('The unused exclusion from a late spouse is capped at ' + money.format(BASIC_EXCLUSION) + ', so only that much is used.');
    if (r.tax > 0) notes.push('Every extra dollar above the exclusion is taxed at 40%. A return (Form 706) is due nine months after death.');
    else if (r.gross + p.gifts > BASIC_EXCLUSION) notes.push('No federal estate tax is due, but a Form 706 is still required because the gross estate plus lifetime taxable gifts exceeds ' + money.format(BASIC_EXCLUSION) + '.');
    else if (r.portable > 0) notes.push('No federal estate tax is due. If this person is married, the executor can file Form 706 to pass the unused ' + money.format(r.portable) + ' of exclusion to the surviving spouse.');
    var note = document.getElementById('etNote');
    if (note) { note.hidden = notes.length === 0; note.textContent = notes.join(' '); }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('etForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
